let welcomeBriefing=null,briefingActive=null;
function englishNarrator(){if(typeof window==='undefined'||!window.speechSynthesis)return null;const voices=window.speechSynthesis.getVoices().filter(v=>/^en(?:-|_)/i.test(v.lang));return voices.find(v=>v.default)||voices.find(v=>/matua|mitchell|daniel|david|alex|male/i.test(v.name))||voices[0]||null}
function stopBriefing(){const active=briefingActive;if(!active)return;briefingActive=null;if(active.video&&!active.video.paused)active.video.pause?.();if(active.timer)clearInterval(active.timer);active.timer=null;active.playing=false;if(active.button)active.button.textContent=active.time>=30?'Replay 30s':'Play 30s';window.speechSynthesis?.cancel()}
function briefingMarkup(preview,video=false){return `<div class="briefing-heading"><div><span>GEOFF IN 30 SECONDS</span><h3>${video?'Your Stakes Day guide':`Race ${preview.race} briefing`}</h3></div><span class="briefing-duration">0:30</span></div>${video?`<video class="welcome-video" controls playsinline preload="none" poster="${esc(preview.poster)}" aria-label="Geoff’s thirty-second guide to Stakes Day"><source src="${esc(preview.video)}" type="video/mp4"><track kind="captions" srclang="en" label="English captions" src="assets/geoff-welcome.vtt"></video>`:`<div class="briefing-stage"><div class="briefing-host"><div class="briefing-geoff"><img src="assets/geoff-source.jpg" alt="Geoff" width="590" height="1280"></div><span>GEOFF<small>Synthetic presenter</small></span></div><h4 class="briefing-scene-title">${esc(preview.scenes[0].title)}</h4><p class="briefing-scene-caption">${esc(preview.scenes[0].caption)}</p><p class="briefing-assumptions"></p></div><progress class="briefing-progress" max="30" value="0" aria-label="Thirty-second briefing progress"></progress>`}<div class="briefing-controls">${video?'':'<button class="briefing-play" type="button">Play 30s</button>'}<button class="briefing-sound" type="button" aria-pressed="true">Checking narration…</button><span class="briefing-status" aria-live="polite">${preview.voice?.recorded?'Animated Geoff · synthetic English narration':'Captioned · synthetic presenter'}</span></div><details class="briefing-transcript"><summary>Read the preview &amp; sources</summary>${preview.scenes.map(s=>`<p>${esc(s.narration)}${s.assumptions?`<small>${esc(s.assumptions)}</small>`:''}</p>`).join('')}${(preview.opinions||[]).map(o=>`<p><b>${esc(o.name)} · ${esc(o.horse)}</b><small>${esc(o.why)} Ground: ${esc(o.ground)} Run: ${esc(o.run)}</small><a href="${esc(o.url)}" target="_blank" rel="noopener">Published view ↗</a></p>`).join('')}${(preview.sources||[]).map(s=>`<a href="${esc(typeof s==='string'?s:s.url)}" target="_blank" rel="noopener">${esc(typeof s==='string'?'Source ↗':s.title+' ↗')}</a>`).join('')}</details>`}
function bindBriefing(box,preview){
 const state={box,preview,time:0,lastScene:-1,playing:false,sound:true,video:box.querySelector('video'),button:box.querySelector('.briefing-play'),soundButton:box.querySelector('.briefing-sound')};box._briefing=state;
 const updateVoice=()=>{if(preview.voice?.recorded){state.soundButton.hidden=true;return}const voice=englishNarrator();state.soundButton.disabled=!voice;state.soundButton.textContent=voice?(state.sound?'Narration · on':'Narration · off'):'Captions only';state.soundButton.setAttribute('aria-pressed',String(!!voice&&state.sound))};
 function sceneAt(time,speak=true){if(time>=30)speak=false;const i=time>=30?preview.scenes.length-1:Math.max(0,preview.scenes.findIndex(s=>time>=s.start&&time<s.end)),scene=preview.scenes[i];if(!scene||i===state.lastScene)return;state.lastScene=i;if(!state.video){box.querySelector('.briefing-scene-title').textContent=scene.title;box.querySelector('.briefing-scene-caption').textContent=scene.caption;box.querySelector('.briefing-assumptions').textContent=scene.assumptions||''}const voice=englishNarrator(),Ctor=window.SpeechSynthesisUtterance;if(speak&&state.sound&&!preview.voice?.recorded&&voice&&Ctor&&state.playing){window.speechSynthesis.cancel();const utterance=new Ctor(scene.narration);utterance.voice=voice;utterance.lang=voice.lang||'en-US';utterance.rate=Math.max(.9,Math.min(1.35,scene.narration.split(/\s+/).length/((scene.end-scene.start)*2.6)));utterance.onerror=e=>{if(!['interrupted','canceled'].includes(e.error))box.querySelector('.briefing-status').textContent='Audio unavailable; captions continue.'};window.speechSynthesis.speak(utterance)}}
 function begin(){if(briefingActive&&briefingActive!==state)stopBriefing();briefingActive=state;state.playing=true;state.lastScene=-1;sceneAt(state.time);}
 if(state.video){state.video.addEventListener('play',()=>{state.time=state.video.currentTime||0;begin()});state.video.addEventListener('timeupdate',()=>{state.time=state.video.currentTime||0;if(state.playing)sceneAt(state.time)});state.video.addEventListener('pause',()=>{if(briefingActive===state)stopBriefing()});state.video.addEventListener('ended',()=>{if(briefingActive===state)stopBriefing()});state.video.addEventListener('seeked',()=>{state.lastScene=-1;if(state.playing)sceneAt(state.video.currentTime||0)})}
 else state.button.onclick=()=>{if(state.playing){stopBriefing();return}if(state.time>=30)state.time=0;begin();state.button.textContent='Pause';const start=Date.now()-state.time*1000;state.timer=setInterval(()=>{state.time=Math.min(30,(Date.now()-start)/1000);box.querySelector('progress').value=state.time;if(state.time>=30){stopBriefing();return}sceneAt(state.time)},200)};
 state.soundButton.onclick=()=>{state.sound=!state.sound;updateVoice();if(briefingActive===state){window.speechSynthesis?.cancel();state.lastScene=-1;sceneAt(state.time)}};updateVoice();window.speechSynthesis?.addEventListener?.('voiceschanged',updateVoice,{once:true});
}
function renderRaceBriefing(){const box=document.getElementById('raceBriefing');if(!box||!race)return;const preview=lateMail?.previews?.[String(race.number)],jump=Date.parse(lateMail?.selections?.[String(race.number)]?.startAt||''),now=Date.now(),valid=preview?.race===race.number&&preview.date===data.date&&Date.parse(preview.preparedAt)<Date.parse(preview.jumpAt)&&Date.parse(preview.preparedAt)>=Date.parse(preview.jumpAt)-600000;
 if(!valid){if(box._briefing&&briefingActive===box._briefing)stopBriefing();box._briefing=null;box.dataset.previewKey='';box.innerHTML=`<div class="briefing-locked"><span>GEOFF’S 30-SECOND RACE PREVIEW</span><p>${Number.isFinite(jump)&&now<jump-600000?`Prepared after the ten-minute check, around ${mailClock(new Date(jump-600000).toISOString())}.`:Number.isFinite(jump)&&now>=jump?'No saved ten-minute preview is available for this race.':'Waiting for a successful saved ten-minute check.'}</p></div>`;return}
 const key=preview.runKey+'-'+preview.preparedAt;if(box.dataset.previewKey===key)return;if(box._briefing&&briefingActive===box._briefing)stopBriefing();box.dataset.previewKey=key;box.innerHTML=briefingMarkup(preview)+`<p class="briefing-saved">Saved before jump · ${mailDate(preview.preparedAt)} · editorial views are attributed, not recorded guest voices.</p>`;bindBriefing(box,preview);
}
function initBriefings(){fetch('welcome-preview.json').then(r=>r.json()).then(preview=>{welcomeBriefing=preview;const box=document.getElementById('welcomeBriefing');box.innerHTML=briefingMarkup(preview,true);bindBriefing(box,preview)}).catch(()=>{document.getElementById('welcomeBriefing').innerHTML='<p class="mail-quiet">The welcome preview is unavailable. The form guide remains ready below.</p>'})}
